val routes = HttpRoutes.of[IO] {
  case GET -> Root / "orders" / id =>
    for {
      order <- orders.find(id)                 // worker services the request
      page   = html("<!DOCTYPE html>")(body(h1(order.id)))   // typed view value
      resp  <- Ok(page)                        // http4s-scalatags sets text/html
    } yield resp
}
